package com.powercms.cms.delivery.navigation;
import com.powercms.cms.content.entity.ContentItemEntity; import com.powercms.cms.content.repo.*; import com.powercms.cms.sitefolder.repo.SiteFolderRepository; import com.powercms.cms.model.repo.ContentTypeRepository; import com.powercms.cms.delivery.RenderDatasetCache; import org.springframework.stereotype.Service; import java.util.*;
@Service public class NavTreeBuilder {
 public static final int MAX_DEPTH=10,MAX_ITEMS=500; private final ContentItemRepository items; private final ContentVersionRepository versions; private final ContentTypeRepository types; private final SiteFolderRepository folders; private final RenderDatasetCache cache; private final com.fasterxml.jackson.databind.ObjectMapper mapper;
 public NavTreeBuilder(ContentItemRepository i,ContentVersionRepository v,ContentTypeRepository t,SiteFolderRepository f,RenderDatasetCache c,com.fasterxml.jackson.databind.ObjectMapper m){items=i;versions=v;types=t;folders=f;cache=c;mapper=m;}
 public record Filter(String contentType,String status,String pathPrefix,String titlePrefix,Set<UUID> excludeIds){} public record Item(String id,String title,String path,String contentType,Map<String,Object> additionalFields,List<Item> children){}
 public List<Item> build(UUID siteId,int depth,Filter filter,boolean preview){int d=Math.max(1,Math.min(depth,MAX_DEPTH));String key=siteId+":"+d+":"+String.valueOf(filter);return cache.getOrLoad(RenderDatasetCache.Region.CONTENT,"nav:"+key,!preview,()->doBuild(siteId,d,filter));}
 private List<Item> doBuild(UUID siteId,int max,Filter f){Map<UUID,String> codes=new HashMap<>();types.findBySiteIdOrderByCodeAsc(siteId).forEach(t->codes.put(t.getId(),t.getCode()));List<Node> nodes=items.findBySiteIdAndStatus(siteId,ContentItemEntity.STATUS_PUBLISHED).stream().filter(x->x.getRoutePath()!=null).limit(MAX_ITEMS).map(x->new Node(x,codes.get(x.getContentTypeId()))).filter(n->allow(n,f)).sorted(Comparator.comparing((Node n)->n.e.getRoutePath()).thenComparing(n->n.e.getTitle(),String.CASE_INSENSITIVE_ORDER).thenComparing(n->n.e.getId())).toList();Map<String,Node> byPath=new LinkedHashMap<>();nodes.forEach(n->byPath.put(n.e.getRoutePath(),n));Map<String,FolderNode> folderNodes=new LinkedHashMap<>();folders.findBySiteIdOrderBySortOrderAscTitleAsc(siteId).stream().filter(com.powercms.cms.sitefolder.entity.SiteFolderEntity::isShowOnMenu).forEach(x->folderNodes.put(x.getPath(),new FolderNode(x)));for(FolderNode n:folderNodes.values()){String parent=parent(n.e.getPath());while(parent!=null&&!folderNodes.containsKey(parent))parent=parent(parent);if(parent!=null)folderNodes.get(parent).folders.add(n);}Map<UUID,FolderNode> folderById=new HashMap<>();folderNodes.values().forEach(fn->folderById.put(fn.e.getId(),fn));for(Node n:nodes){if(n.e.getFolderId()!=null&&folderById.containsKey(n.e.getFolderId())){folderById.get(n.e.getFolderId()).pages.add(n);continue;}if(folderNodes.containsKey(n.e.getRoutePath())){folderNodes.get(n.e.getRoutePath()).pages.add(n);continue;}String parent=parent(n.e.getRoutePath());while(parent!=null&&!folderNodes.containsKey(parent)&&!byPath.containsKey(parent))parent=parent(parent);if(parent!=null&&byPath.containsKey(parent))byPath.get(parent).children.add(n);else if(parent!=null)folderNodes.get(parent).pages.add(n);}Set<Node> child=new HashSet<>();nodes.forEach(n->child.addAll(n.children));Set<Node> inFolder=new HashSet<>();folderNodes.values().forEach(n->inFolder.addAll(n.pages));List<Item> result=new ArrayList<>();folderNodes.values().stream().filter(n->n.e.getParentId()==null||!folderNodes.containsKey(parent(n.e.getPath()))).forEach(n->result.add(folderDto(n,1,max)));nodes.stream().filter(n->!child.contains(n)&&!inFolder.contains(n)).map(n->dto(n,1,max)).filter(Objects::nonNull).forEach(result::add);return List.copyOf(result);}
 private boolean allow(Node n,Filter f){if(f==null)return true;if(f.status()!=null&&!f.status().isBlank()&&!f.status().equals(n.e.getStatus()))return false;if(f.contentType()!=null&&!f.contentType().isBlank()&&!f.contentType().equals(n.code))return false;if(f.pathPrefix()!=null&&!f.pathPrefix().isBlank()&&!n.e.getRoutePath().startsWith(f.pathPrefix()))return false;if(f.titlePrefix()!=null&&!f.titlePrefix().isBlank()&&!n.e.getTitle().startsWith(f.titlePrefix()))return false;return f.excludeIds()==null||!f.excludeIds().contains(n.e.getId());}
 private Item folderDto(FolderNode n,int depth,int max){if(depth>max)return null;Map<String,Object> extra=Map.of("showOnMenu",true,"sortOrder",n.e.getSortOrder(),"folder",true);List<Item> children=new ArrayList<>();n.folders.stream().sorted(Comparator.comparingInt(x->x.e.getSortOrder())).map(x->folderDto(x,depth+1,max)).filter(Objects::nonNull).forEach(children::add);n.pages.stream().map(x->dto(x,depth+1,max)).filter(Objects::nonNull).forEach(children::add);return new Item(n.e.getId().toString(),n.e.getTitle(),n.e.getPath(),"FOLDER",extra,List.copyOf(children));}
 private Item dto(Node n,int depth,int max){if(depth>max)return null;Map<String,Object> extra=new LinkedHashMap<>();Integer ver=n.e.getPublishedVersion();if(ver!=null)versions.findByContentItemIdAndVersion(n.e.getId(),ver).ifPresent(v->{try{Object x=mapper.readValue(v.getFieldValues(),Map.class);if(x instanceof Map<?,?> m)for(String k:List.of("navIcon","navLabel"))if(m.containsKey(k))extra.put(k,m.get(k));}catch(Exception ignored){}});return new Item(n.e.getId().toString(),n.e.getTitle(),n.e.getRoutePath(),n.code,Map.copyOf(extra),n.children.stream().map(c->dto(c,depth+1,max)).filter(Objects::nonNull).toList());}
 private static String parent(String p){if(p==null||"/".equals(p))return null;int i=p.lastIndexOf('/');return i<=0?"/":p.substring(0,i);} private static final class FolderNode{final com.powercms.cms.sitefolder.entity.SiteFolderEntity e;final List<FolderNode> folders=new ArrayList<>();final List<Node> pages=new ArrayList<>();FolderNode(com.powercms.cms.sitefolder.entity.SiteFolderEntity e){this.e=e;}} private static final class Node{final ContentItemEntity e;final String code;final List<Node> children=new ArrayList<>();Node(ContentItemEntity e,String c){this.e=e;code=c;}}
}
